// Proves the browser pipeline reproduces the Python one. Fixture and expected
// values are generated by src/export_web_models.py's companion step.

import { loadModels, analyse, analyseMany } from "./pipeline.js";


const out = document.getElementById("out");
const verdict = document.getElementById("verdict");
const log = s => { out.textContent += s + "\n"; };

async function maskFromPng(url) {
  // createImageBitmap rather than Image.decode(): decode() can stall when the
  // page is not compositing (hidden tab / headless run), which would hang the test.
  const bmp = await createImageBitmap(await (await fetch(url)).blob());
  const c = document.createElement("canvas");
  c.width = bmp.width;
  c.height = bmp.height;
  const ctx = c.getContext("2d", { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0);
  const d = ctx.getImageData(0, 0, c.width, c.height).data;
  const mask = new Uint8Array(c.width * c.height);
  for (let i = 0, p = 0; i < mask.length; i++, p += 4) mask[i] = d[p] > 127 ? 1 : 0;
  return { mask, width: c.width, height: c.height };
}

(async () => {
  try {
    const expected = await (await fetch("test/expected.json")).json();
    await loadModels("models");
    const front = await maskFromPng("test/front.png");
    const side = await maskFromPng("test/side.png");

    log(`fixture ${expected.photo_id.slice(0, 12)}  ${front.width}x${front.height}`);
    log(`profile ${expected.height_cm} cm, ${expected.weight_kg} kg, age ${expected.age}, sex ${expected.sex}\n`);

    const t0 = performance.now();
    const got = analyse(front, side, {
      heightCm: expected.height_cm, weightKg: expected.weight_kg,
      age: expected.age, sex: expected.sex,
    });
    const ms = performance.now() - t0;

    let failures = 0;
    const cmp = (name, a, b, tol = 0.05) => {
      const ok = Math.abs(a - b) <= tol;
      if (!ok) failures++;
      log(`  ${ok ? "ok  " : "FAIL"} ${name.padEnd(28)} browser ${String(a).padStart(7)}   python ${String(b).padStart(7)}`);
    };

    log("Stage 1 - measurements (cm)");
    for (const [k, v] of Object.entries(expected.measurements)) cmp(k, got.measurements[k], v);

    log("\nStage 2 - body composition");
    for (const [tgt, v] of Object.entries(expected.composition)) {
      cmp(`${tgt} estimate`, got.composition[tgt].estimate, v.estimate);
      cmp(`${tgt} low`, got.composition[tgt].low, v.low);
      cmp(`${tgt} high`, got.composition[tgt].high, v.high);
    }

    log("\nAgainst BodyM tape measurements (accuracy, not parity)");
    for (const [k, v] of Object.entries(expected.ground_truth)) {
      const d = got.measurements[k] - v;
      log(`       ${k.padEnd(28)} predicted ${String(got.measurements[k]).padStart(6)}   actual ${String(v).padStart(6)}   err ${d >= 0 ? "+" : ""}${d.toFixed(1)}`);
    }

    log(`\ninference time: ${ms.toFixed(0)} ms`);

    // ---- multi-frame combination (the scan path) --------------------------
    // Three pairs: the true masks, plus two eroded variants standing in for
    // the frame-to-frame segmentation wobble a real scan produces.
    log("\nMulti-frame combination (scan path)");
    // Real erosion. open3 is erode-then-dilate, which is a no-op on a smooth
    // mask - using it here would compare three identical inputs and prove nothing.
    const erodeOnce = (mask, w, h) => {
      const out = new Uint8Array(w * h);
      for (let y = 1; y < h - 1; y++) {
        for (let x = 1; x < w - 1; x++) {
          const i = y * w + x;
          out[i] = (mask[i] && mask[i - 1] && mask[i + 1] && mask[i - w] && mask[i + w]) ? 1 : 0;
        }
      }
      return out;
    };
    const variant = m => ({ mask: erodeOnce(m.mask, m.width, m.height), width: m.width, height: m.height });
    const pairs = [
      { front, side },
      { front: variant(front), side: variant(side) },
      { front: variant(variant(front)), side: variant(variant(side)) },
    ];
    const singles = pairs.map(p => analyse(p.front, p.side, {
      heightCm: expected.height_cm, weightKg: expected.weight_kg,
      age: expected.age, sex: expected.sex,
    }).measurements.waist);
    const many = analyseMany(pairs, {
      heightCm: expected.height_cm, weightKg: expected.weight_kg,
      age: expected.age, sex: expected.sex,
    });

    log(`  per-frame waist: ${singles.map(v => v.toFixed(1)).join(", ")}`);
    log(`  combined waist:  ${many.measurements.waist.toFixed(1)}  (spread ${many.frameSpread.waist.toFixed(1)})`);
    cmp("frame count", many.frameCount, 3, 0);

    const sorted = [...singles].sort((a, b) => a - b);
    const withinRounding = Math.abs(many.measurements.waist - sorted[1]) <= 0.1;
    if (!withinRounding) failures++;
    log(`  ${withinRounding ? "ok  " : "FAIL"} combined value is the median, not the mean or an extreme`);

    // a single wild frame must not move the median
    const poisoned = [...pairs, { front: variant(variant(variant(front))), side }];
    const withOutlier = analyseMany(poisoned, {
      heightCm: expected.height_cm, weightKg: expected.weight_kg,
      age: expected.age, sex: expected.sex,
    }).measurements.waist;
    const robust = Math.abs(withOutlier - many.measurements.waist) < 2.0;
    if (!robust) failures++;
    log(`  ${robust ? "ok  " : "FAIL"} adding a bad frame moves the result by only ${Math.abs(withOutlier - many.measurements.waist).toFixed(2)} cm`);
    verdict.textContent = failures === 0
      ? "PASS - browser matches Python on every value"
      : `FAIL - ${failures} value(s) diverged`;
    verdict.className = "verdict " + (failures === 0 ? "pass" : "fail");
    window.__selftest = { failures, ms, got, expected };
  } catch (err) {
    verdict.textContent = "ERROR - " + err.message;
    verdict.className = "verdict fail";
    log(err.stack);
    window.__selftest = { failures: -1, error: err.message };
  }
})();
